WITH RECURSIVE x10 AS (SELECT x8.v51293, CUME_DIST() OVER (ORDER BY x8.v51293) FROM x14 UNION SELECT LAST_DAY('x') + 0.0 FROM x15 WHERE x8.v51293 LIKE '%Constructed hypergraph%') SELECT x8.v51293, x8.v51293, HEX(x8.v51293) = HEX(x8.v51293) AS x4, x8.v51293 FROM v51292 AS x8 WHERE x8.v51293 IN (0.5, 0.6, 0.7, 0.8, 0.9)